contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        (uint oldUnlock, uint oldBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Put{value: amount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint newUnlock, uint newBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted || (newUnlock >= oldUnlock && newBal >= oldBal));
    }

    receive() external payable {}
}

